var raceMgr = UnityEngine.Object.FindObjectOfType<RaceManager>();
UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
// Reproduce exactly what -garagecheck does, then report what the camera sees.
var hidden = new System.Collections.Generic.List<GameObject>();
foreach (var car in raceMgr.cars)
{
    if (car == null || car == raceMgr.player) continue;
    var body = car.GetComponentInChildren<Transform>();
    if (body != null && body.gameObject.activeSelf) { body.gameObject.SetActive(false); hidden.Add(body.gameObject); }
}
var t = garage.transform;
var camPos = t.position + t.rotation * new Vector3(3.4f, 1.75f, -5.4f);
var look = t.position + Vector3.up * 0.75f;
sb.AppendLine("player pos=" + t.position + " fwd=" + t.forward);
sb.AppendLine("camera would be at " + camPos + " looking at " + look);
sb.AppendLine("hidden rivals=" + hidden.Count);
// What renderers are within 12 m of that camera and in front of it?
var dir = (look - camPos).normalized;
foreach (Renderer r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None))
{
    Vector3 c = r.bounds.center;
    Vector3 to = c - camPos;
    float d = to.magnitude;
    if (d > 14f) continue;
    if (Vector3.Dot(to.normalized, dir) < 0.55) continue;
    if (!r.gameObject.activeInHierarchy) continue;
    sb.AppendLine("  VISIBLE " + r.gameObject.name + " parent=" + (r.transform.parent ? r.transform.parent.name : "-") + " dist=" + d.ToString("F1") + " size=" + r.bounds.size.ToString("F2"));
}
Debug.Log("PROBE10 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
